HEIGHTS = [round(h, 2) for h in np.arange(0.06, 0.2401, 0.02)]       # pedestal commands tried (the finder's valid range at this stance ends near 0.23)
# The genome is the 7 joints (degrees) and the stance's offset from the current staging stance, dx and dy in cm (+-6: the finder's tolerance there is 14.9 cm; the finder rerun grades the real region).
LO = np.array([0.0, -30.0, -35.0, 10.0, -30.0, -35.0, -80.0, -6.0, -6.0])         # sampling bounds (j2 at most 0: its upper limit is +10 deg; j4 at least 10 and the joints' limits less 10 deg)
HI = np.array([45.0, 0.0, 35.0, 130.0, 30.0, 35.0, 80.0, 6.0, 6.0])
SIGMA0 = np.array([9.0, 5.0, 12.0, 7.0, 7.0, 7.0, 12.0, 2.5, 2.5])                 # first step sizes
REQ = STANCE_REQUIREMENTS                                              # the same limits as the stance finder's selection and home_pose_test
OCC_MAX, FRAMING_MIN = REQ["occlusion_max_hidden"], REQ["framing_min_slack"]
BEAKER_HIDDEN_UNIT = 0.05                                              # the beaker may hide 0 %: one unit of margin is 5 % of its pixels hidden (below zero), +CAP when none is
CAP = 3.0                                                              # margins are capped here
SCORE_CAP = 0.3                                                        # the search key counts the smallest margin only up to here (then it prefers a smaller arm coverage)
COVERAGE_WEIGHT = 3.0                                                  # key points per unit of arm coverage (a fraction of the eagle image: 10 % of the image = 0.3)


class Search:
    """The evaluation of poses on one scene (kept for the whole search)."""

    def __init__(self, heights=HEIGHTS, yaw_max=15.0):
        self.heights, self.yaw_max = list(heights), yaw_max
        self.ev = HPC.Evaluator()
        m = self.ev.m
        self.C = grasp_cfg(m, "left")
        self.stance0 = HPC.CURRENT_STANCE
        self.shift = (0.0, 0.0)                                           # (dx, dy) of the stance being evaluated, metres
        self.base_geoms = None

    def stance(self, h):
        """The stance being evaluated: the current staging stance shifted by self.shift, at pedestal command h."""
        return (self.stance0[0] + self.shift[0], self.stance0[1] + self.shift[1], self.stance0[2], h)

    # ---- hard conditions
    def geometry(self, stance):
        """The left gripper's pose at a stance, from the model: approach pitch and yaw relative to the heading, closing-axis elevation (degrees), the tool point relative to the shoulder."""
        chk, m = self.ev.chk, self.ev.m
        chk.place(stance)
        d = chk.d
        R = d.body("openarm_left_hand_tcp").xmat.reshape(3, 3)
        a, y = R @ np.asarray(self.C["approach_axis"], float), R @ np.asarray(self.C["closing_axis"], float)
        yaw = stance[2]
        f, l = np.array([math.cos(yaw), math.sin(yaw), 0.0]), np.array([-math.sin(yaw), math.cos(yaw), 0.0])
        p = d.body("openarm_left_hand_tcp").xpos + R @ np.asarray(self.C["pad_center_in_tcp"], float)
        sh = d.body("openarm_left_link0").xpos
        base = d.body("openarm_body_link0").xpos
        rel = p - sh
        return {"pitch_deg": math.degrees(math.asin(np.clip(a[2], -1, 1))), "yaw_deg": math.degrees(math.atan2(a @ l, a @ f)), "roll_deg": math.degrees(math.asin(np.clip(y[2], -1, 1))),
                "forward_m": float(rel @ f + (sh - base) @ f), "up_from_shoulder_m": float(rel[2]), "lateral_m": float((p - base) @ l)}

    @staticmethod
    def violation(g, yaw_max=15.0):
        v = 0.0
        v += max(0.0, abs(g["pitch_deg"]) - 10.0) / 10.0 + max(0.0, abs(g["yaw_deg"]) - yaw_max) / yaw_max + max(0.0, abs(g["roll_deg"]) - 8.0) / 8.0
        v += max(0.0, -0.17 - g["up_from_shoulder_m"]) / 0.05 + max(0.0, g["up_from_shoulder_m"] + 0.04) / 0.05
        v += max(0.0, 0.20 - g["forward_m"]) / 0.05 + max(0.0, 0.15 - g["lateral_m"]) / 0.05
        return v

    # ---- requirements
    def occlusion_margins(self, stance, targets):
        """The occlusion margins (see the module docstring) with the neck at the framing pose `targets`, from the pixel-area measure; also the measurement."""
        occ = self.ev.chk.occlusion(stance, targets)
        hb, hh = occ["beaker_hidden_frac"], occ["hotplate_hidden_frac"]
        lim = OCC_MAX["hotplate"]
        return {"occlusion_beaker": CAP if hb <= 0.0 else -hb / BEAKER_HIDDEN_UNIT, "occlusion_hotplate": (lim - hh) / lim}, occ

    def cheap(self, stance):
        """The margins that need no neck solve: the clearances (all groups, the fingers alone, the placed beaker) and the joint margins."""
        ev = self.ev
        c = ev.clearances(stance)
        mg = {}
        for k, v in c.items():
            if k in MIN_CLEARANCE:
                mg[f"clear_{k}"] = (v["mm"] - v["min_mm"]) / v["min_mm"]
        for k in ("fingers vs bench", "fingers vs hotplate"):
            mg[f"clear_{k}"] = (c[k]["mm"] - 40.0) / 40.0
        bh = c["arms to a beaker standing on the hotplate"]["mm"]
        mg["clear_placed_beaker"] = CAP if bh is None else (bh - 1000 * REQ["placed_beaker_min_clearance"]) / (1000 * REQ["placed_beaker_min_clearance"])
        jm = ev.joint_margins()["min_deg"]
        mg["joint"] = (jm - 10.0) / 10.0
        return {k: min(v, CAP) for k, v in mg.items()}, c

    def expensive(self, stance, cheap_min):
        """The margins that need the neck solve: the neck spread, the occlusion of the beaker and the hotplate, the framing slack with both grippers."""
        ev = self.ev
        ns = ev.chk.neck_spread(stance, n=4)
        mg = {"neck": (0.06 - ns["spread"]) / 0.06}
        om, occ = self.occlusion_margins(stance, ns["targets"])
        mg.update(om)
        if min(cheap_min, mg["neck"], *om.values()) > -0.5:                                # the framing slack is the slow part: only for poses that are not hopeless
            fr = ev.framing(stance)
            mg["framing"] = (fr["with_grippers_pct"] / 100 - FRAMING_MIN) / FRAMING_MIN
            return {k: min(v, CAP) for k, v in mg.items()}, {"neck_spread": ns["spread"], "occlusion": occ, "framing": fr}
        mg["framing"] = -1.0
        return mg, {"neck_spread": ns["spread"], "occlusion": occ, "framing": None}

    def score(self, q_deg, log_fh=None):
        """Evaluates a pose: the hard conditions, then the margins at the pedestal heights; returns the record (best score over the heights)."""
        q_deg = np.asarray(q_deg, float)
        HPC.set_home(q_deg[:7])
        self.ev.refresh_home()
        self.shift = (0.01 * q_deg[7], 0.01 * q_deg[8])
        rec = {"q_deg": [float(v) for v in q_deg[:7]], "offset_cm": [float(q_deg[7]), float(q_deg[8])]}
        g = self.geometry(self.stance(0.12))
        rec["geometry"] = g
        viol = self.violation(g, self.yaw_max)
        if viol > 0:
            rec.update(score=-3.0 - viol, key=-3.0 - viol, stage="hard", violation=viol)
        else:
            rows = []
            for h in self.heights:
                st = self.stance(h)
                mg, _ = self.cheap(st)
                rows.append((min(mg.values()), h, mg))
            rows.sort(key=lambda r: -r[0])
            best = None
            for cheap_min, h, mg in rows[:3]:
                if cheap_min < -0.5:
                    break
                st = self.stance(h)
                mg2, info = self.expensive(st, cheap_min)
                allm = {**mg, **mg2}
                sc = min(allm.values())
                cov = None if info["occlusion"] is None else info["occlusion"]["arm_frac"]
                key = min(sc, SCORE_CAP) + 0.02 * float(np.mean(list(allm.values()))) - (COVERAGE_WEIGHT * cov if cov is not None else 0.0)       # David 2026-10-20: arm coverage of the eagle image
                if best is None or key > best["key"]:
                    best = {"score": sc, "key": key, "arm_frac": cov, "height": h, "margins": allm, "limiting": min(allm, key=allm.get), "info": info}
            if best is None:
                cheap_min, h, mg = rows[0]
                best = {"score": cheap_min - 0.5, "key": cheap_min - 0.5 + 0.02 * float(np.mean(list(mg.values()))), "height": h, "margins": mg, "limiting": min(mg, key=mg.get), "info": None}
                rec["stage"] = "cheap"
            else:
                rec["stage"] = "full"
            rec.update(best)
        if log_fh:
            log_fh.write(json.dumps(rec) + "\n")
            log_fh.flush()
        return rec


def search(args):
    out = Path(args.out)
    out.mkdir(parents=True, exist_ok=True)
    S = Search()
    rng = np.random.default_rng(args.seed)
    starts = {"C": np.r_[HPC.CANDIDATES["C"], 0.0, 0.0], "B": np.r_[HPC.CANDIDATES["B"], 0.0, 0.0], "C_wide": np.r_[(15, -5, -6, 132, 0, 0, 25), 0.0, 0.0]}
    t0 = time.time()
    overall = None
    names = list(starts) + ["best"]
    per = 60 * args.minutes / len(names)
    with open(out / args.evals_file("search"), "a") as fh:
        for si, name in enumerate(names):
            mean = overall[1].copy() if name == "best" else starts[name].copy()
            sigma = SIGMA0.copy()
            best_run = None
            ts = time.time()
            rec = S.score(mean, fh)
            best_run = (rec["key"], mean.copy(), rec)
            print(f"[{name}] start: score {rec['score']:+.3f} ({rec.get('limiting')}) stage {rec['stage']}", flush=True)
            gen = 0
            while time.time() - ts < per:
                gen += 1
                pop = [np.clip(mean + sigma * rng.standard_normal(9), LO, HI) for _ in range(args.pop)]
                recs = [S.score(q, fh) for q in pop]
                order = np.argsort([-r["key"] for r in recs])
                parents = [pop[i] for i in order[:max(2, args.pop // 4)]]
                if recs[order[0]]["key"] > best_run[0]:
                    best_run = (recs[order[0]]["key"], pop[order[0]].copy(), recs[order[0]])
                mean = 0.5 * np.mean(parents, axis=0) + 0.5 * best_run[1]
                sigma = np.maximum(sigma * 0.94, SIGMA0 * 0.1)
                full = sum(r["stage"] == "full" for r in recs)
                br = best_run[2]
                print(f"[{name}] gen {gen:2d} ({(time.time() - t0) / 60:4.1f} min): generation best {recs[order[0]]['score']:+.3f}, run best {br['score']:+.3f} ({br.get('limiting')}) at q {np.round(best_run[1][:7], 1).tolist()} "
                      f"offset {np.round(best_run[1][7:], 1).tolist()} cm height {br.get('height')}; {full}/{len(recs)} fully evaluated, {sum(r['stage'] == 'hard' for r in recs)} broke a hard condition", flush=True)
            if overall is None or best_run[2]["score"] > overall[2]["score"]:
                overall = best_run
            print(f"[{name}] run done: best score {best_run[2]['score']:+.3f}; overall best {overall[2]['score']:+.3f}", flush=True)
    print("SEARCH DONE", flush=True)


def load_best(out, top, evals="evals.jsonl"):
    """The best distinct fully evaluated poses from an evaluations file (default evals.jsonl, the v2 search with the ray occlusion measure, whose ranks 1 to 3 the reports and the finder reruns use): poses closer than 6 degrees (largest joint difference) to a better one are skipped."""
    recs = [json.loads(l) for l in open(Path(out) / evals)]
    recs = [r for r in recs if r["stage"] == "full"]
    recs.sort(key=lambda r: -r["score"])
    keep = []
    for r in recs:
        if all(np.abs(np.array(r["q_deg"]) - np.array(k["q_deg"])).max() > 6.0 for k in keep):
            keep.append(r)
        if len(keep) == top:
            break
    return keep


def report(args):
    out = Path(args.out)
    best = load_best(out, args.top, args.evals_file())
    summary = []
    for rank, r in enumerate(best, 1):
        HPC.set_home(r["q_deg"])
        ev = HPC.Evaluator()
        dx, dy = r["offset_cm"]
        st = (HPC.CURRENT_STANCE[0] + 0.01 * dx, HPC.CURRENT_STANCE[1] + 0.01 * dy, HPC.CURRENT_STANCE[2], r["height"])
        full = ev.full(st, out_png=out / f"rank{rank}")
        print(f"=== rank {rank}: left arm {np.round(r['q_deg'], 1).tolist()} deg, stance offset {r['offset_cm']} cm, pedestal {r['height']}, score {r['score']:+.3f} (limited by {r['limiting']})\n" + HPC.fmt_full(full), flush=True)
        print("  margins (1.0 = one limit's worth): " + ", ".join(f"{k} {v:+.2f}" for k, v in sorted(r["margins"].items(), key=lambda kv: kv[1])), flush=True)
        print(f"  gripper geometry: {({k: round(v, 3) for k, v in r['geometry'].items()})}", flush=True)
        summary.append({"rank": rank, **r, "full": full})
        del ev
    SFM.save(out / "best3.json", summary)
    print("REPORT DONE", flush=True)


def occlusion_area(args):
    """The pixel-based occlusion (how much of the beaker and the hotplate the robot hides from the eagle camera) of pose A and of the best distinct poses."""
    out = Path(args.out)
    rows = []
    items = [("A", list(HPC.CANDIDATES["A"]), HPC.CURRENT_STANCE, None)]
    for rank, r in enumerate(load_best(out, args.top, args.evals_file()), 1):
        dx, dy = r["offset_cm"]
        items.append((f"rank{rank}", r["q_deg"], (HPC.CURRENT_STANCE[0] + 0.01 * dx, HPC.CURRENT_STANCE[1] + 0.01 * dy, HPC.CURRENT_STANCE[2], r["height"]), r["score"]))
    for name, q, st, score in items:
        HPC.set_home(q)
        ev = HPC.Evaluator()
        o = ev.occlusion_area(st)
        print(f"{name}: stance x {st[0]:.3f} y {st[1]:.3f} pedestal {st[3]:.3f}: beaker {100 * o['beaker_hidden_frac']:.1f} % hidden ({o['beaker_px']} of {o['beaker_px_free']} px), hotplate {100 * o['hotplate_hidden_frac']:.1f} % hidden ({o['hotplate_px']} of {o['hotplate_px_free']} px)", flush=True)
        rows.append({"name": name, "q_deg": list(map(float, q)), "stance": list(map(float, st)), **o})
        del ev
    SFM.save(out / "occlusion_area.json", rows)
    print("OCCLUSION DONE", flush=True)


VARIANTS_FILE = "variants.json"


def load_variants(out):
    f = Path(out) / VARIANTS_FILE
    return json.loads(f.read_text()) if f.exists() else {}


def make_variant(args):
    """A variant of a search pose with the grippers pointing straighter forward (David 2026-10-20): only the forearm turn and the wrist joints (j3, j5, j6, j7) change; j1, j2, j4 and the stance stay.

    Step 1, kinematics only: random poses around the base pose in j3, j5, j6, j7 (within the sampling bounds and +-args.spread degrees), kept if they meet the hard conditions with the
    gripper yaw within +-args.yaw_max degrees (yaw is measured from the heading; positive = toward the robot's left = outward for the left arm). Step 2: the feasible poses closest to the base
    pose (spread out by at least 2 degrees) are fully evaluated at the base pose's stance and pedestal height; the best by the search key (smallest margin up to SCORE_CAP, then small arm
    coverage) is stored in variants.json under args.variant_name, together with every evaluation (variant_evals.jsonl).
    """
    out = Path(args.out)
    out.mkdir(parents=True, exist_ok=True)
    base = load_best(out, args.variant_of, "evals.jsonl")[args.variant_of - 1]
    S = Search(heights=[base["height"]], yaw_max=args.yaw_max)
    q0 = np.array(base["q_deg"] + base["offset_cm"], float)
    S.shift = (0.01 * q0[7], 0.01 * q0[8])
    st = S.stance(base["height"])
    free = [2, 4, 5, 6]
    rng = np.random.default_rng(args.seed)
    HPC.set_home(q0[:7])
    S.ev.refresh_home()
    g0 = S.geometry(st)
    print(f"base: rank {args.variant_of}, q {np.round(q0[:7], 1).tolist()}, stance offset {np.round(q0[7:], 2).tolist()} cm, pedestal {base['height']}; gripper yaw {g0['yaw_deg']:+.1f} deg, "
          f"pitch {g0['pitch_deg']:+.1f}, roll {g0['roll_deg']:+.1f}; score {base['score']:+.3f}", flush=True)
    feasible = []
    t0 = time.time()
    for _ in range(args.samples):
        q = q0.copy()
        q[free] += rng.uniform(-args.spread, args.spread, len(free))
        q[:7] = np.clip(q[:7], LO[:7], HI[:7])
        HPC.set_home(q[:7])
        S.ev.refresh_home()
        g = S.geometry(st)
        if S.violation(g, args.yaw_max) == 0.0:
            feasible.append((float(np.linalg.norm((q - q0)[free])), q.copy(), g))
    print(f"{len(feasible)} of {args.samples} samples meet the hard conditions with |yaw| <= {args.yaw_max} deg ({time.time() - t0:.0f} s)", flush=True)
    feasible.sort(key=lambda r: r[0])
    picked = []
    for d, q, g in feasible:
        if all(np.abs(q[free] - p[1][free]).max() > 2.0 for p in picked):
            picked.append((d, q, g))
        if len(picked) >= args.candidates:
            break
    recs = []
    with open(out / "variant_evals.jsonl", "a") as fh:
        for i, (d, q, g) in enumerate(picked):
            rec = S.score(q, fh)
            rec["distance_deg"] = d
            recs.append(rec)
            cov = rec.get("arm_frac")
            print(f"  candidate {i + 1}/{len(picked)}: moved {d:.1f} deg, q {np.round(q[:7], 1).tolist()}, yaw {g['yaw_deg']:+.1f}: score {rec['score']:+.3f} ({rec.get('limiting')}), "
                  f"arm coverage {'-' if cov is None else f'{100 * cov:.1f} %'}, stage {rec['stage']}", flush=True)
    full = [r for r in recs if r["stage"] == "full"]
    if not full:
        print("VARIANT: no candidate was fully evaluated", flush=True)
        return
    bestv = max(full, key=lambda r: r["key"])
    variants = load_variants(out)
    variants[args.variant_name] = {"q_deg": bestv["q_deg"], "offset_cm": bestv["offset_cm"], "height": bestv["height"], "score": bestv["score"], "limiting": bestv["limiting"], "arm_frac": bestv.get("arm_frac"),
                                   "margins": bestv["margins"], "geometry": bestv["geometry"], "base_rank": args.variant_of, "yaw_max": args.yaw_max}
    SFM.save(out / VARIANTS_FILE, variants)
    print(f"VARIANT {args.variant_name}: q {np.round(bestv['q_deg'], 1).tolist()} yaw {bestv['geometry']['yaw_deg']:+.1f} deg, score {bestv['score']:+.3f} (limited by {bestv['limiting']}), arm coverage "
          f"{100 * bestv['arm_frac']:.1f} %", flush=True)
    print("VARIANT DONE", flush=True)


def finder(args):
    out = Path(args.out)
    if args.variant:
        best, name = load_variants(out)[args.variant], f"search_{args.variant}_{args.tag}"
    else:
        best, name = load_best(out, args.rank, args.evals_file())[args.rank - 1], f"search_rank{args.rank}_{args.tag}"
    fa = types.SimpleNamespace(xy_half=0.06, xy_step=0.02)
    HPC.run_finder(name, best["q_deg"], out / name, fa)
    print("FINDER DONE", flush=True)


def main():
    ap = argparse.ArgumentParser(description=__doc__.split("\n")[1])
    ap.add_argument("--search", action="store_true")
    ap.add_argument("--report", action="store_true")
    ap.add_argument("--finder", nargs="?", const=1, type=int, default=None)
    ap.add_argument("--occlusion-area", action="store_true", help="pixel-based occlusion of the beaker and the hotplate for pose A and the best poses")
    ap.add_argument("--make-variant", action="store_true", help="make a variant of rank --variant-of with the grippers straighter forward (j3, j5, j6, j7 only), stored in variants.json")
    ap.add_argument("--variant-of", type=int, default=2)
    ap.add_argument("--variant-name", default="rank2_straight")
    ap.add_argument("--variant", default=None, help="--finder: run the finder for this variant of variants.json instead of a rank")
    ap.add_argument("--yaw-max", type=float, default=6.0, help="--make-variant: the largest gripper yaw from the heading, degrees")
    ap.add_argument("--samples", type=int, default=6000)
    ap.add_argument("--spread", type=float, default=20.0, help="--make-variant: the sampling range around the base pose in j3, j5, j6, j7, degrees")
    ap.add_argument("--candidates", type=int, default=40, help="--make-variant: poses fully evaluated")
    ap.add_argument("--tag", default="widest_range", help="--finder: the output folder is search_rank<N>_<tag> under --out (default widest_range: placed-beaker requirement, widest-range ranking)")
    ap.add_argument("--minutes", type=float, default=40.0)
    ap.add_argument("--pop", type=int, default=16)
    ap.add_argument("--seed", type=int, default=0)
    ap.add_argument("--top", type=int, default=3)
    ap.add_argument("--out", default=str(PROJECT_ROOT / "data" / "home_pose_search"))
    ap.add_argument("--evals", default=None, help="the evaluations file under --out: --search appends to it (default evals_v3_pixel.jsonl: the margins changed, so it does not mix with the "
                    "ray-occlusion evaluations of evals.jsonl); the others read it (default evals.jsonl)")
    args = ap.parse_args()
    args.evals_file = lambda mode="read": args.evals or ("evals_v3_pixel.jsonl" if mode == "search" else "evals.jsonl")
    if args.finder is not None:
        args.rank = args.finder
    if args.make_variant:
        make_variant(args)
    if args.search:
        search(args)
    if args.report:
        report(args)
    if args.occlusion_area:
        occlusion_area(args)
    if args.finder is not None:
        finder(args)


if __name__ == "__main__":
    main()
